// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 minSum, uint256 lockTime, uint256 putAmount, uint256 collectAmount) public {
        minSum = bound(minSum, 0, 1e30);
        lockTime = bound(lockTime, 0, 365 days);
        putAmount = bound(putAmount, 0, 1e30);
        collectAmount = bound(collectAmount, 0, 1e30);

        // Initialize
        c.SetMinSum(minSum);
        c.SetLogFile(address(0));
        c.Initialized();

        // Put some ether (simulate with arbitrary sender)
        vm.deal(address(this), putAmount);
        (bool sent, ) = address(c).call{value: putAmount}(abi.encodeWithSignature("Put(uint256)", lockTime));
        if (!sent) return;

        // warp past lock time
        vm.warp(block.timestamp + lockTime + 1);

        // Record MinSum before Collect
        uint256 minSumBefore = c.MinSum();

        // Call Collect
        (bool success, ) = address(c).call{value: 0}(abi.encodeWithSignature("Collect(uint256)", collectAmount));

        // Assert: after Collect, MinSum is unchanged
        assertTrue(c.MinSum() == minSumBefore, "MinSum changed after Collect");
    }
}

